<?php require __DIR__.'/inc/header.php';$title='Dashboard';$revenue=(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE order_status IN ('confirmed','processing','ready_to_ship','shipped','delivered')")->fetchColumn();$orders=(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn();$pending=(int)db()->query("SELECT COUNT(*) FROM orders WHERE order_status IN ('pending','confirmed','processing')")->fetchColumn();$low=(int)db()->query('SELECT COUNT(*) FROM variants WHERE stock<=low_stock_threshold')->fetchColumn();$customers=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$recent=db()->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();?><div class="grid grid-cols-2 lg:grid-cols-5 gap-3"><?php foreach([['Revenue',money($revenue),'solar:wad-of-money-linear'],['Orders',$orders,'solar:bag-4-linear'],['Pending',$pending,'solar:clock-circle-linear'],['Low Stock',$low,'solar:danger-triangle-linear'],['Customers',$customers,'solar:users-group-rounded-linear']] as $x):?><div class="bg-white border rounded-2xl p-4 soft"><span class="iconify text-2xl" data-icon="<?=$x[2]?>"></span><div class="text-xs text-slate-400 mt-3"><?=$x[0]?></div><div class="text-2xl font-black mt-1"><?=$x[1]?></div></div><?php endforeach;?></div><div class="grid lg:grid-cols-[1.15fr_.85fr] gap-6 mt-6"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black">Sales Overview</div><div class="h-64 mt-5 flex items-end gap-2"><?php $days=db()->query("SELECT date(created_at) d, SUM(total) total FROM orders WHERE created_at>=datetime('now','-6 day') GROUP BY date(created_at) ORDER BY d")->fetchAll();$mx=max(1,...array_column($days,'total'));foreach($days as $d):?><div class="flex-1 h-full flex flex-col justify-end items-center"><div class="w-full max-w-10 bg-slate-950 rounded-t-xl" style="height:<?=max(6,((float)$d['total']/$mx)*90)?>%"></div><div class="text-[10px] text-slate-400 mt-2"><?=e(substr($d['d'],5))?></div></div><?php endforeach;?></div></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black">Quick Actions</div><div class="grid grid-cols-2 gap-3 mt-4"><a href="/admin/products.php?create=1" class="p-4 rounded-xl bg-slate-100 font-bold">Add Product</a><a href="/admin/orders.php" class="p-4 rounded-xl bg-slate-100 font-bold">Manage Orders</a><a href="/admin/inventory.php" class="p-4 rounded-xl bg-slate-100 font-bold">Stock</a><a href="/admin/categories.php" class="p-4 rounded-xl bg-slate-100 font-bold">Categories</a></div></div></div><div class="bg-white border rounded-2xl mt-6 overflow-hidden soft"><div class="p-5 font-black">Recent Orders</div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3 text-left">Order</th><th class="p-3 text-left">Customer</th><th class="p-3 text-left">Total</th><th class="p-3 text-left">Status</th></tr></thead><tbody><?php foreach($recent as $o):?><tr class="border-t"><td class="p-3 font-bold"><a href="/admin/orders.php?id=<?=$o['id']?>"><?=e($o['order_number'])?></a></td><td class="p-3"><?=e($o['customer_name'])?></td><td class="p-3 font-bold"><?=money($o['total'])?></td><td class="p-3"><?=ucwords(str_replace('_',' ',e($o['order_status'])))?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php';?>
